#!/usr/bin/env python
"""Rebuilds summary.tsv from the *_calibration.tsv files already generated by
generate_deepptmpred_calibration.py. That script only writes summary.tsv at the
end of ITS own run (all the types passed in --ptm-types), so
after two partial runs (11 types + 6 types) the summary was left with only
the last 6. This script aggregates all 17 without re-executing the model.

## Threshold rule: FPR-constrained TPR-max, not Youden's J

Youden's J (maximizing tpr-fpr) degenerates when the AUROC of a small sample
is poor: the point that maximizes J can be the synthetic "reject everything" that
sklearn.roc_curve prepends (threshold = max(score)+1), which gave
threshold=inf for o_linked_glycosylation in the first version of this script.

Rather than inventing a rule of our own, the one that DeepPTMPred itself
implements was ported, verified by reading its real code
(``DeepPTMPred/pred/train_PTM/trainer.py``, the functions
``optimize_threshold_high_specificity``/``_high_specificity2``/``_f1``,
lines ~130-173) and confirmed empirically against the results it did
publish (``pred/train_PTM/result/results_*/``, the FP Rate column):

- trainer.py itself has a real dispatch bug (L356-364, ``if`` instead
  of ``elif``): the phosphorylation branch (FPR<=0.18) is overridden by the
  ``else`` (FPR<=0.20), and only n_linked_glycosylation reaches the F1-max branch,
  which in the published results gives it FP Rate=0.94 (F1-max over imbalanced
  data is just as fragile as Youden's J, the same kind of failure).
  That bug is in a TRAINING script that this project never executes
  (only predict.py is used, for inference), so the vendored trainer.py is not
  touched, but the bug is not replicated here either.
- It is standardized on FPR-constrained TPR-max for all 17 types (avoiding F1-max
  entirely, given the confirmed case of degeneration), with the stricter
  bound (FPR<=0.18, the real ``optimize_threshold_high_specificity``
  function, never reached because of the bug but still valid) reserved for
  phosphorylation, exactly as the paper describes (Briefings in Bioinformatics
  27(3) bbag321) as the type that demands high specificity; the rest use
  FPR<=0.20 (``optimize_threshold_high_specificity2``, the one that in fact
  produced the published metrics for 16/17 types because of the dispatch bug).
  It falls back to 0.5 if no candidate threshold meets the bound, just as the
  original code does.
"""
from pathlib import Path

import numpy as np
import pandas as pd
from sklearn.metrics import roc_auc_score, roc_curve

CALIB_DIR = Path(__file__).resolve().parent.parent / "DeepPTMPred" / "data" / "calibration"

# FPR maximo tolerado por tipo -- ver docstring del modulo.
HIGH_SPECIFICITY_MAX_FPR = 0.18
DEFAULT_MAX_FPR = 0.20
HIGH_SPECIFICITY_TYPES = {"phosphorylation"}


def _fpr_constrained_threshold(labels: np.ndarray, probs: np.ndarray, max_fpr: float) -> float:
    """Port fiel de optimize_threshold_high_specificity(2) de trainer.py: entre los
    umbrales con fpr <= max_fpr, el que maximiza tpr; fallback 0.5 si ninguno cumple.

    Extra respecto al original (necesario en muestra chica/ruidosa, no en el
    codigo de trainer.py porque nunca se corrio sobre datos tan pequenos):
    sklearn.roc_curve antepone un punto sintetico "rechazar todo"
    (fpr=0, tpr=0, threshold=max(score)+1) que satisface cualquier max_fpr
    trivialmente. thresholds[0] nunca es un umbral real (max(score)+1 > 1,
    predict.py jamas podria alcanzarlo), asi que se excluye antes de buscar
    el maximo -- si no, un desempate a tpr=0 lo elige y da threshold=inf.
    """
    fpr, tpr, thresholds = roc_curve(labels, probs)
    fpr, tpr, thresholds = fpr[1:], tpr[1:], thresholds[1:]
    valid = fpr <= max_fpr
    if not valid.any():
        return 0.5
    return float(thresholds[valid][np.argmax(tpr[valid])])


def main() -> None:
    rows = []
    for f in sorted(CALIB_DIR.glob("*_calibration.tsv")):
        ptm_type = f.stem.replace("_calibration", "")
        df = pd.read_csv(f, sep="\t")
        n_pos = int((df["label"] == 1).sum())
        n_neg = int((df["label"] == 0).sum())
        if n_pos == 0 or n_neg == 0:
            print(f"{ptm_type}: solo una clase presente ({n_pos} pos / {n_neg} neg), se omite del resumen.")
            continue
        auroc = roc_auc_score(df["label"], df["probability"])
        max_fpr = HIGH_SPECIFICITY_MAX_FPR if ptm_type in HIGH_SPECIFICITY_TYPES else DEFAULT_MAX_FPR
        threshold = _fpr_constrained_threshold(df["label"].to_numpy(), df["probability"].to_numpy(), max_fpr)
        rows.append({
            "ptm_type": ptm_type, "n_sites": len(df), "n_pos": n_pos, "n_neg": n_neg,
            "n_proteins": df["protein_id"].nunique(), "auroc": auroc,
            "max_fpr": max_fpr, "suggested_threshold": threshold,
        })

    summary = pd.DataFrame(rows).sort_values("ptm_type").reset_index(drop=True)
    out_path = CALIB_DIR / "summary.tsv"
    summary.to_csv(out_path, sep="\t", index=False)
    print(f"\nResumen escrito en {out_path} ({len(summary)} tipos):")
    print(summary.to_string(index=False))


if __name__ == "__main__":
    main()
